struct BfmeDispatchObject
{
	unsigned char m_pad00[0x74];
	int m_id;
	unsigned char m_pad78[0x18c];
	BfmeDispatchInterface *m_dispatch;
};

struct BfmeDispatchListNode
{
	BfmeDispatchListNode *m_next;
	BfmeDispatchListNode *m_previous;
	BfmeDispatchObject *m_object;
};

struct BfmeDispatchTreeNode
{
	unsigned char m_pad00[4];
	BfmeDispatchTreeNode *m_childA;
	BfmeDispatchTreeNode *m_childB;
	BfmeDispatchTreeNode *m_childC;
	int m_key;
};

struct BfmeDispatchTree
{
	unsigned char m_pad00[4];
	BfmeDispatchTreeNode *m_root;
};

class BfmeMissingObjectDispatch
{
public:
	void dispatchMissing(void *first, void *second);
};

void BfmeMissingObjectDispatch::dispatchMissing(void *first, void *second)
{
	BfmeDispatchListNode *head =
		*(BfmeDispatchListNode **)((char *)this - 0xac);
	BfmeDispatchListNode *node = head->m_next;

	while (node != head)
	{
		BfmeDispatchObject *object = node->m_object;
		BfmeDispatchTree *tree =
			*(BfmeDispatchTree **)((char *)this + 0x30);
		BfmeDispatchTreeNode *sentinel = (BfmeDispatchTreeNode *)tree;
		BfmeDispatchTreeNode *cursor = tree->m_root;
		BfmeDispatchTreeNode *found = sentinel;
		int key = object->m_id;
		node = node->m_next;

		while (cursor != 0)
		{
			if (cursor->m_key < key)
			{
				found = cursor;
				cursor = cursor->m_childB;
			}
			else
			{
				cursor = cursor->m_childC;
			}
		}

		if (found != sentinel && key < found->m_key)
			found = sentinel;

		if (found == sentinel && object->m_dispatch != 0)
			object->m_dispatch->dispatchMissing(first, second);
	}
}
